package Bloque_2;

//********************************************
//PROGRAMA QUE CAMBIA EL VALOR DE UNA VARIABLE
//********************************************


public class CambioValor {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int puntuacion = 0;
		System.out.println("Puntuacion = " + puntuacion);
		
		puntuacion = 50;
		System.out.println("Puntuacion = " + puntuacion);
		
		puntuacion = 100;
		System.out.println("Puntuacion = " + puntuacion);

	}

}
